package com.math10.teachercontent;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.math10.common.exception.BusinessException;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.security.SecureRandom;
import java.util.*;

@Service @RequiredArgsConstructor
public class QuestionTransformationService {
 private final JdbcTemplate jdbc; private final ObjectMapper mapper; private final SecureRandom random=new SecureRandom();

 public Map<String,Object> transform(long questionId,long teacherId,Map<String,Object> requested){
  Map<String,Object> q=owned(questionId,teacherId);if(!"REVIEWED".equals(q.get("status")))throw new BusinessException("Giáo viên phải duyệt câu gốc trước");if(!Boolean.TRUE.equals(q.get("transformable")))throw new BusinessException(Objects.toString(q.get("transform_block_reason"),"Câu chưa đủ điều kiện biến đổi"));
  Generated g=generate(q,requested==null?Map.of():requested);boolean valid=validate(g);String validation=valid?"VALID":"INVALID";
  Long variant=jdbc.queryForObject("insert into question_variants(source_question_id,transformation_type,content,answer,solution,parameters_json,options_json,rule_code,validation_status,validation_json,created_at,updated_at) values(?,'PARAMETER_CHANGE',?,?,?,cast(? as jsonb),cast(? as jsonb),?,?,cast(? as jsonb),now(),now()) returning id",Long.class,questionId,g.content(),g.answer(),g.solution(),json(g.parameters()),json(g.options()),g.rule(),validation,json(Map.of("valid",valid,"checks",g.checks())));
  jdbc.update("insert into question_transformations(source_question_id,variant_id,rule_code,input_parameters,generated_parameters,validation_result,created_by,created_at,updated_at) values(?,?,?,cast(? as jsonb),cast(? as jsonb),cast(? as jsonb),?,now(),now())",questionId,variant,g.rule(),json(requested==null?Map.of():requested),json(g.parameters()),json(Map.of("valid",valid,"checks",g.checks())),teacherId);
  return jdbc.queryForMap("select * from question_variants where id=?",variant);
 }
 private Generated generate(Map<String,Object> q,Map<String,Object> p){String signature=q.get("math_signature").toString(),intent=q.get("question_intent").toString();return switch(signature){case "LINEAR_EQUATION"->linearEquation(p);case "QUADRATIC_EQUATION"->quadraticEquation(p);case "LINEAR_FUNCTION"->linearFunction(intent,p);case "QUADRATIC_FUNCTION"->quadraticFunction(intent,p);default->throw new BusinessException("Dạng toán chưa có rule biến đổi");};}
 private Generated linearEquation(Map<String,Object> p){int a=nonZero(p,"a",pick(-6,6)),x=value(p,"xSolution",pick(-8,8)),b=value(p,"b",pick(-10,10)),c=a*x+b;String left=term(a,"x")+signed(b);Map<String,String> options=xOptions(x);return generated("LINEAR_EQUATION_V1","Giải phương trình "+left+" = "+c,"x = "+x,"Thay và kiểm tra: "+a+"·"+x+signed(b)+" = "+c,Map.of("a",a,"b",b,"c",c,"xSolution",x),options,List.of("a != 0","c = a*xSolution + b"));}
 private Generated quadraticEquation(Map<String,Object> p){int r1=value(p,"r1",pick(-10,10)),r2=value(p,"r2",pick(-10,10));if(r1==r2)r2=r1==10?9:r1+1;int a=allowedA(p),b=-a*(r1+r2),c=a*r1*r2;String equation=polynomial(a,b,c)+" = 0";Map<String,String> options=pairOptions(r1,r2);return generated("QUADRATIC_EQUATION_V1","Giải phương trình "+equation,"x = "+r1+" hoặc x = "+r2,a+"(x"+signed(-r1)+")(x"+signed(-r2)+") = 0",Map.of("a",a,"b",b,"c",c,"r1",r1,"r2",r2),options,List.of("r1 != r2","a in {-3,-2,-1,1,2,3}","Viete coefficients valid"));}
 private Generated linearFunction(String intent,Map<String,Object> p){int a=nonZero(p,"a",pick(-6,6)),root=value(p,"root",pick(-8,8)),b=-a*root,x=value(p,"x",pick(-5,5));if("FIND_FUNCTION_VALUE".equals(intent)){int y=a*x+b;return generated("LINEAR_FUNCTION_VALUE_V1","Cho hàm số y = "+term(a,"x")+signed(b)+". Tính y khi x = "+x,String.valueOf(y),"y = "+a+"·"+x+signed(b)+" = "+y,Map.of("a",a,"b",b,"x",x,"y",y),numberOptions(y,-y,y+a,y-a),List.of("y = a*x+b"));}if("IDENTIFY_COEFFICIENT".equals(intent))return generated("LINEAR_FUNCTION_COEFFICIENT_V1","Cho hàm số y = "+term(a,"x")+signed(b)+". Xác định hệ số góc",String.valueOf(a),"Hệ số của x là "+a,Map.of("a",a,"b",b),numberOptions(a,b,-a,-b),List.of("a != 0"));return generated("LINEAR_FUNCTION_ROOT_V1","Tìm nghiệm của hàm số y = "+term(a,"x")+signed(b),"x = "+root,"0 = "+a+"x"+signed(b),Map.of("a",a,"b",b,"root",root),xOptions(root),List.of("b = -a*root"));}
 private Generated quadraticFunction(String intent,Map<String,Object> p){int a=allowedA(p),h=value(p,"h",pick(-6,6)),k=value(p,"k",pick(-8,8)),b=-2*a*h,c=a*h*h+k;String f=polynomial(a,b,c);if("FIND_ROOT".equals(intent)){int r1=value(p,"r1",pick(-8,8)),r2=value(p,"r2",pick(-8,8));if(r1==r2)r2=r1+1;b=-a*(r1+r2);c=a*r1*r2;f=polynomial(a,b,c);return generated("QUADRATIC_FUNCTION_ROOT_V1","Tìm nghiệm của hàm số y = "+f,"x = "+r1+" hoặc x = "+r2,a+"(x"+signed(-r1)+")(x"+signed(-r2)+")",Map.of("a",a,"r1",r1,"r2",r2,"b",b,"c",c),pairOptions(r1,r2),List.of("r1 != r2","function factors valid"));}if("IDENTIFY_COEFFICIENT".equals(intent))return generated("QUADRATIC_FUNCTION_COEFFICIENT_V1","Cho hàm số y = "+f+". Xác định hệ số của x^2",String.valueOf(a),"Hệ số của x^2 là "+a,Map.of("a",a,"b",b,"c",c),numberOptions(a,b,c,-a),List.of("a != 0"));if("FIND_AXIS".equals(intent))return generated("QUADRATIC_AXIS_V1","Cho hàm số y = "+f+". Tìm trục đối xứng","x = "+h,"Dạng đỉnh: y = "+a+"(x"+signed(-h)+")^2"+signed(k),Map.of("a",a,"h",h,"k",k,"b",b,"c",c),textOptions("x = "+h,"x = "+(-h),"y = "+h,"y = "+(-h),"x = "+(h+1),"x = "+(h-1)),List.of("b = -2*a*h","axis = h"));if("FIND_FUNCTION_VALUE".equals(intent)){int x=value(p,"x",pick(-5,5)),y=a*(x-h)*(x-h)+k;return generated("QUADRATIC_FUNCTION_VALUE_V1","Cho hàm số y = "+f+". Tính y khi x = "+x,String.valueOf(y),"y = "+a+"("+x+signed(-h)+")^2"+signed(k)+" = "+y,Map.of("a",a,"h",h,"k",k,"x",x,"y",y),numberOptions(y,-y,y+a,y-a),List.of("vertex form evaluation"));}return generated("QUADRATIC_VERTEX_V1","Cho hàm số y = "+f+". Tìm tọa độ đỉnh","("+h+", "+k+")","Dạng đỉnh: y = "+a+"(x"+signed(-h)+")^2"+signed(k),Map.of("a",a,"h",h,"k",k,"b",b,"c",c),textOptions("("+h+", "+k+")","("+(-h)+", "+k+")","("+h+", "+(-k)+")","("+(-h)+", "+(-k)+")","("+(h+1)+", "+k+")","("+h+", "+(k+1)+")","("+(h+1)+", "+(k+1)+")"),List.of("b = -2*a*h","c = a*h^2+k","vertex = (h,k)"));}
 private boolean validate(Generated g){Set<String> values=new HashSet<>(g.options().values());return !g.content().isBlank()&&!g.answer().isBlank()&&g.options().size()==4&&values.size()==4&&values.contains(g.answer())&&!g.checks().isEmpty();}
 private Generated generated(String rule,String content,String answer,String solution,Map<String,Object> params,Map<String,String> options,List<String> checks){return new Generated(rule,content,answer,solution,params,options,checks);}
 private Map<String,String> numberOptions(int correct,int b,int c,int d){return textOptions(String.valueOf(correct),String.valueOf(b),String.valueOf(c),String.valueOf(d),String.valueOf(correct+1),String.valueOf(correct-1),String.valueOf(correct+2));}
 private Map<String,String> xOptions(int correct){return textOptions("x = "+correct,"x = "+(-correct),"x = "+(correct+1),"x = "+(correct-1),"x = "+(correct+2),"x = "+(correct-2));}
 private Map<String,String> pairOptions(int r1,int r2){return textOptions(pair(r1,r2),pair(-r1,-r2),pair(r1,-r2),pair(-r1,r2),pair(r1+1,r2),pair(r1,r2+1),pair(r1-1,r2));}
 private String pair(int a,int b){return "x = "+a+" hoặc x = "+b;}
 // Không chắp chuỗi để cho đủ bốn phương án. Bản trước làm đúng thế: khi đáp án bằng 0 thì "x = 0"
 // và "x = -0" trùng nhau nên chỉ còn ba phương án, và vòng while đẻ ra "x = 0 + 1" — một lựa chọn
 // vô nghĩa mà validate() vẫn đếm là hợp lệ, vì nó chỉ kiểm bốn chuỗi có khác nhau không. Nay hết
 // ứng viên thì trả rỗng để validate() đánh INVALID: thà không sinh được biến thể còn hơn sinh ra
 // phương án bịa rồi đưa cho học sinh chọn.
 private Map<String,String> textOptions(String... candidates){LinkedHashSet<String> unique=new LinkedHashSet<>();for(String x:candidates){unique.add(x);if(unique.size()==4)break;}if(unique.size()<4)return Map.of();Iterator<String> it=unique.iterator();return Map.of("A",it.next(),"B",it.next(),"C",it.next(),"D",it.next());}
 private int value(Map<String,Object> p,String key,int fallback){Object x=p.get(key);return x instanceof Number n?n.intValue():fallback;}private int nonZero(Map<String,Object> p,String key,int fallback){int x=value(p,key,fallback);return x==0?1:x;}private int allowedA(Map<String,Object> p){int x=value(p,"a",List.of(-3,-2,-1,1,2,3).get(random.nextInt(6)));return Set.of(-3,-2,-1,1,2,3).contains(x)?x:1;}private int pick(int min,int max){return random.nextInt(max-min+1)+min;}
 private String term(int a,String x){return a==1?x:a==-1?"-"+x:a+x;}private String signed(int n){return n==0?"":n>0?" + "+n:" - "+Math.abs(n);}private String polynomial(int a,int b,int c){return term(a,"x^2")+signedTerm(b,"x")+signed(c);}private String signedTerm(int n,String x){return n==0?"":n>0?" + "+term(n,x):" - "+term(Math.abs(n),x);}
 private Map<String,Object> owned(long id,long teacher){List<Map<String,Object>> x=jdbc.queryForList("select q.* from extracted_questions q join teacher_source_documents d on d.id=q.source_document_id where q.id=? and d.owner_teacher_id=? and q.deleted_at is null and d.deleted_at is null",id,teacher);if(x.isEmpty())throw new BusinessException("Không tìm thấy câu hỏi");return x.get(0);}
 private String json(Object value){try{return mapper.writeValueAsString(value);}catch(JsonProcessingException e){throw new BusinessException("Không thể lưu dữ liệu biến đổi");}}
 private record Generated(String rule,String content,String answer,String solution,Map<String,Object> parameters,Map<String,String> options,List<String> checks){}
}
